1	// SessionTracker.ts
2	// Manages session state, transcript arrays, context windows, and epoch compaction.
3	// Extracted from IntelligenceManager to decouple state management from LLM orchestration.
4	
5	import { RecapLLM } from './llm';
6	import { isVerboseLogging } from './verboseLog';
7	
8	export interface TranscriptSegment {
9	    marker?: string;
10	    speaker: string;
11	    text: string;
12	    timestamp: number;
13	    final: boolean;
14	    confidence?: number;
15	}
16	
17	export interface SuggestionTrigger {
18	    context: string;
19	    lastQuestion: string;
20	    confidence: number;
21	}
22	
23	// Context item matching Swift ContextManager structure
24	export interface ContextItem {
25	    role: 'interviewer' | 'user' | 'assistant';
26	    text: string;
27	    timestamp: number;
28	}
29	
30	export interface AssistantResponse {
31	    text: string;
32	    timestamp: number;
33	    questionContext: string;
34	}
35	
36	export class SessionTracker {
37	    // Context management (mirrors Swift ContextManager)
38	    private contextItems: ContextItem[] = [];
39	    private readonly contextWindowDuration: number = 120; // 120 seconds
40	    private readonly maxContextItems: number = 500;
41	
42	    // Last assistant message for follow-up mode
43	    private lastAssistantMessage: string | null = null;
44	
45	    // Temporal RAG: Track all assistant responses in session for anti-repetition
46	    private assistantResponseHistory: AssistantResponse[] = [];
47	
48	    // Meeting metadata
49	    private currentMeetingMetadata: {
50	        title?: string;
51	        calendarEventId?: string;
52	        source?: 'manual' | 'calendar';
53	    } | null = null;
54	
55	    // Full Session Tracking (Persisted)
56	    private fullTranscript: TranscriptSegment[] = [];
57	    private fullUsage: any[] = []; // UsageInteraction
58	    private sessionStartTime: number = Date.now();
59	
60	    // Rolling summarization: epoch summaries preserve early context when arrays are compacted
61	    private static readonly MAX_EPOCH_SUMMARIES = 5;
62	    private transcriptEpochSummaries: string[] = [];
63	    private isCompacting: boolean = false;
64	
65	    // Track interim interviewer segment
66	    private lastInterimInterviewer: TranscriptSegment | null = null;
67	
68	    // Detected coding question from transcript or screenshot extraction
69	    private detectedCodingQuestion: string | null = null;
70	    private codingQuestionSource: 'screenshot' | 'transcript' | null = null;
71	    private codingQuestionSetAt: number | null = null;
72	
73	    // Rolling buffer for multi-segment interviewer question detection
74	    private recentInterviewerBuffer: { text: string; timestamp: number }[] = [];
75	    private static readonly INTERVIEWER_BUFFER_WINDOW_MS = 5 * 60 * 1000; // 5 minutes
76	    // Screenshot-detected question stays sticky for 3 min before transcript can override
77	    private static readonly SCREENSHOT_STALE_MS = 3 * 60 * 1000;
78	
79	    // Reference to RecapLLM for epoch summarization (injected later)
80	    private recapLLM: RecapLLM | null = null;
81	
82	    // ============================================
83	    // Configuration
84	    // ============================================
85	
86	    public setRecapLLM(recapLLM: RecapLLM | null): void {
87	        this.recapLLM = recapLLM;
88	    }
89	
90	    public setMeetingMetadata(metadata: any): void {
91	        this.currentMeetingMetadata = metadata;
92	    }
93	
94	    public getMeetingMetadata() {
95	        return this.currentMeetingMetadata;
96	    }
97	
98	    public clearMeetingMetadata(): void {
99	        this.currentMeetingMetadata = null;
100	    }
101	
102	    // ============================================
103	    // Coding Question Tracking
104	    // ============================================
105	
106	    /**
107	     * Set the current coding question.
108	     * Priority rules (avoids stale Q1 blocking Q2 detection in multi-question interviews):
109	     *  - Screenshot → always stored immediately (explicit user action via Solve)
110	     *  - Transcript → stored if nothing is known yet, OR if existing question is also from
111	     *    transcript (newer detection = newer question), OR if screenshot question is stale
112	     *    (> 3 min old — user likely moved to the next question)
113	     */
114	    setCodingQuestion(question: string, source: 'screenshot' | 'transcript'): void {
115	        const now = Date.now();
116	        const trimmed = question.trim();
117	        if (!trimmed) return;
118	
119	        if (this.detectedCodingQuestion === null) {
120	            // Nothing stored — accept any source
121	            this.detectedCodingQuestion = trimmed;
122	            this.codingQuestionSource = source;
123	            this.codingQuestionSetAt = now;
124	            console.log(`[SessionTracker] Coding question stored (source: ${source}): "${trimmed.substring(0, 80)}..."`);
125	            return;
126	        }
127	
128	        if (source === 'screenshot') {
129	            // Screenshot always updates immediately (explicit user Solve action)
130	            this.detectedCodingQuestion = trimmed;
131	            this.codingQuestionSource = source;
132	            this.codingQuestionSetAt = now;
133	            console.log(`[SessionTracker] Coding question updated via screenshot: "${trimmed.substring(0, 80)}..."`);
134	            return;
135	        }
136	
137	        // source === 'transcript'
138	        const isStale = this.codingQuestionSetAt !== null
139	            && (now - this.codingQuestionSetAt) > SessionTracker.SCREENSHOT_STALE_MS;
140	        const canOverride = this.codingQuestionSource === 'transcript' || isStale;
141	
142	        if (canOverride) {
143	            this.detectedCodingQuestion = trimmed;
144	            this.codingQuestionSource = source;
145	            this.codingQuestionSetAt = now;
146	            console.log(`[SessionTracker] Coding question updated via transcript (prev was ${this.codingQuestionSource}, stale=${isStale}): "${trimmed.substring(0, 80)}..."`);
147	        } else {
148	            console.log(`[SessionTracker] Transcript question ignored — screenshot question is recent (< ${SessionTracker.SCREENSHOT_STALE_MS / 1000}s)`);
149	        }
150	    }
151	
152	    getDetectedCodingQuestion(): { question: string | null; source: 'screenshot' | 'transcript' | null } {
153	        return { question: this.detectedCodingQuestion, source: this.codingQuestionSource };
154	    }
155	
156	    clearCodingQuestion(): void {
157	        this.detectedCodingQuestion = null;
158	        this.codingQuestionSource = null;
159	        this.codingQuestionSetAt = null;
160	        this.recentInterviewerBuffer = [];
161	    }
162	
163	    /**
164	     * Heuristic to decide if an interviewer statement looks like a coding question.
165	     * Requires ≥2 of the signal patterns and minimum length to avoid false positives
166	     * on casual conversation ("can you implement X?" → yes, "sounds good!" → no).
167	     */
168	    private looksLikeCodingQuestion(text: string): boolean {
169	        if (text.length < 50) return false;
170	        const patterns = [
171	            /\b(implement|write|code|solve|design|build|create)\b/i,
172	            /\b(given\s+(an?|the)\s+(array|string|list|tree|graph|matrix|number|integer|node|linked list|stack|queue|heap))\b/i,
173	            /\b(return|find\s+(all|the|a|any)|count|check\s+if|determine|calculate|maximize|minimize|sort)\b/i,
174	            /\b(function|method|algorithm|data structure|class)\b/i,
175	            /\b(O\(n\)|time complexity|space complexity|optimal|efficient|brute force)\b/i,
176	            /\b(two sum|three sum|binary search|dynamic programming|BFS|DFS|palindrome|anagram|substring|subarray|rotation)\b/i,
177	        ];
178	        const matchCount = patterns.filter(p => p.test(text)).length;
179	        return matchCount >= 2;
180	    }
181	
182	    // ============================================
183	    // Context Management
184	    // ============================================
185	
186	    /**
187	     * Add a transcript segment to context.
188	     * Only stores FINAL transcripts.
189	     * Returns { role, isRefinementCandidate } so the engine can decide whether to trigger follow-up.
190	     */
191	    addTranscript(segment: TranscriptSegment): { role: 'interviewer' | 'user' | 'assistant' } | null {
192	        if (!segment.final) return null;
193	
194	        const role = this.mapSpeakerToRole(segment.speaker);
195	        const text = segment.text.trim();
196	
197	        if (!text) return null;
198	
199	        // Deduplicate: check if this exact item already exists
200	        const lastItem = this.contextItems[this.contextItems.length - 1];
201	        if (lastItem &&
202	            lastItem.role === role &&
203	            Math.abs(lastItem.timestamp - segment.timestamp) < 500 &&
204	            lastItem.text === text) {
205	            return null;
206	        }
207	
208	        this.contextItems.push({
209	            role,
210	            text,
211	            timestamp: segment.timestamp
212	        });
213	
214	        this.evictOldEntries();
215	
216	        // Filter out internal system prompts that might be passed via IPC
217	        const isInternalPrompt = text.startsWith("You are a real-time interview assistant") ||
218	            text.startsWith("You are a helper") ||
219	            text.startsWith("CONTEXT:");
220	
221	        if (!isInternalPrompt) {
222	            // Add to session transcript
223	            this.fullTranscript.push(segment);
224	            // Compact transcript with summarization instead of losing early context
225	            // Fire-and-forget: sync context; errors are caught internally
226	            void this.compactTranscriptIfNeeded().catch(e =>
227	                console.warn('[SessionTracker] compactTranscript error (non-fatal):', e)
228	            );
229	        }
230	
231	        return { role };
232	    }
233	
234	    /**
235	     * Add assistant-generated message to context
236	     */
237	    addAssistantMessage(text: string): void {
238	        console.log(`[SessionTracker] addAssistantMessage called with:`, text.substring(0, 50));
239	
240	        // Natively-style filtering
241	        if (!text) return;
242	
243	        const cleanText = text.trim();
244	        if (cleanText.length < 10) {
245	            console.warn(`[SessionTracker] Ignored short message (<10 chars)`);
246	            return;
247	        }
248	
249	        if (cleanText.includes("I'm not sure") || cleanText.includes("I can't answer")) {
250	            console.warn(`[SessionTracker] Ignored fallback message`);
251	            return;
252	        }
253	
254	        this.contextItems.push({
255	            role: 'assistant',
256	            text: cleanText,
257	            timestamp: Date.now()
258	        });
259	
260	        // Also add to fullTranscript so it persists in the session history (and summaries)
261	        this.fullTranscript.push({
262	            speaker: 'assistant',
263	            text: cleanText,
264	            timestamp: Date.now(),
265	            final: true,
266	            confidence: 1.0
267	        });
268	
269	        // Compact transcript with summarization instead of losing early context
270	        // Fire-and-forget: sync context; errors are caught internally
271	        void this.compactTranscriptIfNeeded().catch(e =>
272	            console.warn('[SessionTracker] compactTranscript error (non-fatal):', e)
273	        );
274	
275	        this.lastAssistantMessage = cleanText;
276	
277	        // Temporal RAG: Track response history for anti-repetition
278	        this.assistantResponseHistory.push({
279	            text: cleanText,
280	            timestamp: Date.now(),
281	            questionContext: this.getLastInterviewerTurn() || 'unknown'
282	        });
283	
284	        // Keep history bounded (last 10 responses)
285	        if (this.assistantResponseHistory.length > 10) {
286	            this.assistantResponseHistory = this.assistantResponseHistory.slice(-10);
287	        }
288	
289	        console.log(`[SessionTracker] lastAssistantMessage updated, history size: ${this.assistantResponseHistory.length}`);
290	        this.evictOldEntries();
291	    }
292	
293	    /**
294	     * Handle incoming transcript from native audio service
295	     */
296	    handleTranscript(segment: TranscriptSegment): { role: 'interviewer' | 'user' | 'assistant' } | null {
297	        // Track interim segments for interviewer to prevent data loss on stop
298	        if (segment.speaker === 'user') {
299	            if (isVerboseLogging() && (Math.random() < 0.05 || segment.final)) {
300	                console.log(`[SessionTracker] RX User Segment: Final=${segment.final} Text="${segment.text.substring(0, 50)}..."`);
301	            }
302	        }
303	        if (segment.speaker === 'interviewer') {
304	            if (isVerboseLogging() && (Math.random() < 0.05 || segment.final)) {
305	                console.log(`[SessionTracker] RX Interviewer Segment: Final=${segment.final} Text="${segment.text.substring(0, 50)}..."`);
306	            }
307	
308	            if (!segment.final) {
309	                this.lastInterimInterviewer = segment;
310	            } else {
311	                this.lastInterimInterviewer = null;
312	
313	                // Add segment to rolling buffer and evict old entries
314	                this.recentInterviewerBuffer.push({ text: segment.text, timestamp: segment.timestamp });
315	                const bufferCutoff = Date.now() - SessionTracker.INTERVIEWER_BUFFER_WINDOW_MS;
316	                this.recentInterviewerBuffer = this.recentInterviewerBuffer.filter(e => e.timestamp >= bufferCutoff);
317	
318	                // Test single segment first; if no match, test accumulated recent turns
319	                // (interviewer may state a problem across multiple speech segments)
320	                if (this.looksLikeCodingQuestion(segment.text)) {
321	                    this.setCodingQuestion(segment.text, 'transcript');
322	                } else if (this.recentInterviewerBuffer.length > 1) {
323	                    const combinedText = this.recentInterviewerBuffer.map(e => e.text).join(' ');
324	                    if (this.looksLikeCodingQuestion(combinedText)) {
325	                        this.setCodingQuestion(combinedText, 'transcript');
326	                    }
327	                }
328	            }
329	        }
330	
331	        return this.addTranscript(segment);
332	    }
333	
334	    // ============================================
335	    // Context Accessors
336	    // ============================================
337	
338	    /**
339	     * Get context items within the last N seconds
340	     */
341	    getContext(lastSeconds: number = 120): ContextItem[] {
342	        const cutoff = Date.now() - (lastSeconds * 1000);
343	        return this.contextItems.filter(item => item.timestamp >= cutoff);
344	    }
345	
346	    getLastAssistantMessage(): string | null {
347	        return this.lastAssistantMessage;
348	    }
349	
350	    getAssistantResponseHistory(): AssistantResponse[] {
351	        return this.assistantResponseHistory;
352	    }
353	
354	    getLastInterimInterviewer(): TranscriptSegment | null {
355	        return this.lastInterimInterviewer;
356	    }
357	
358	    /**
359	     * Get formatted context string for LLM prompts
360	     */
361	    getFormattedContext(lastSeconds: number = 120): string {
362	        const items = this.getContext(lastSeconds);
363	        return items.map(item => {
364	            const label = item.role === 'interviewer' ? 'INTERVIEWER' :
365	                item.role === 'user' ? 'ME' :
366	                    'ASSISTANT (PREVIOUS SUGGESTION)';
367	            return `[${label}]: ${item.text}`;
368	        }).join('\n');
369	    }
370	
371	    /**
372	     * Get the last interviewer turn
373	     */
374	    getLastInterviewerTurn(): string | null {
375	        for (let i = this.contextItems.length - 1; i >= 0; i--) {
376	            if (this.contextItems[i].role === 'interviewer') {
377	                return this.contextItems[i].text;
378	            }
379	        }
380	        return null;
381	    }
382	
383	    /**
384	     * Get full session context from accumulated transcript (User + Interviewer + Assistant)
385	     */
386	    getFullSessionContext(): string {
387	        const recentTranscript = this.fullTranscript.map(segment => {
388	            const role = this.mapSpeakerToRole(segment.speaker);
389	            const label = role === 'interviewer' ? 'INTERVIEWER' :
390	                role === 'user' ? 'ME' :
391	                    'ASSISTANT';
392	            return `[${label}]: ${segment.text}`;
393	        }).join('\n');
394	
395	        // Prepend epoch summaries for full session context preservation
396	        if (this.transcriptEpochSummaries.length > 0) {
397	            const epochContext = this.transcriptEpochSummaries.join('\n---\n');
398	            return `[SESSION HISTORY - EARLIER DISCUSSION]\n${epochContext}\n\n[RECENT TRANSCRIPT]\n${recentTranscript}`;
399	        }
400	
401	        return recentTranscript;
402	    }
403	
404	    // ============================================
405	    // Session Data Accessors (for MeetingPersistence)
406	    // ============================================
407	
408	    getFullTranscript(): TranscriptSegment[] {
409	        return this.fullTranscript;
410	    }
411	
412	    getFullUsage(): any[] {
413	        return this.fullUsage;
414	    }
415	
416	    getSessionStartTime(): number {
417	        return this.sessionStartTime;
418	    }
419	
420	    // ============================================
421	    // Usage Tracking
422	    // ============================================
423	
424	    /**
425	     * Cap usage array with simple eviction (usage doesn't need summarization)
426	     */
427	    capUsageArray(): void {
428	        if (this.fullUsage.length > 500) {
429	            this.fullUsage = this.fullUsage.slice(-500);
430	        }
431	    }
432	
433	    /**
434	     * Public method to log usage from external sources (e.g. IPC direct chat)
435	     */
436	    logUsage(type: string, question: string, answer: string): void {
437	        this.fullUsage.push({
438	            type,
439	            timestamp: Date.now(),
440	            question,
441	            answer
442	        });
443	    }
444	
445	    pushUsage(entry: any): void {
446	        this.fullUsage.push(entry);
447	        this.capUsageArray();
448	    }
449	
450	    // ============================================
451	    // Interim Transcript Flush
452	    // ============================================
453	
454	    /**
455	     * Force-save any pending interim transcript (called on meeting stop)
456	     */
457	    flushInterimTranscript(): void {
458	        if (this.lastInterimInterviewer) {
459	            console.log('[SessionTracker] Force-saving pending interim transcript:', this.lastInterimInterviewer.text);
460	            const finalSegment = { ...this.lastInterimInterviewer, final: true };
461	            this.addTranscript(finalSegment);
462	            this.lastInterimInterviewer = null;
463	        }
464	    }
465	
466	    // ============================================
467	    // Reset
468	    // ============================================
469	
470	    reset(): void {
471	        this.contextItems = [];
472	        this.fullTranscript = [];
473	        this.fullUsage = [];
474	        this.transcriptEpochSummaries = [];
475	        this.sessionStartTime = Date.now();
476	        this.lastAssistantMessage = null;
477	        this.assistantResponseHistory = [];
478	        this.lastInterimInterviewer = null;
479	        this.detectedCodingQuestion = null;
480	        this.codingQuestionSource = null;
481	        this.codingQuestionSetAt = null;
482	        this.recentInterviewerBuffer = [];
483	    }
484	
485	    // ============================================
486	    // Private Helpers
487	    // ============================================
488	
489	    mapSpeakerToRole(speaker: string): 'interviewer' | 'user' | 'assistant' {
490	        if (speaker === 'user') return 'user';
491	        if (speaker === 'assistant') return 'assistant';
492	        return 'interviewer'; // system audio = interviewer
493	    }
494	
495	    private evictOldEntries(): void {
496	        const cutoff = Date.now() - (this.contextWindowDuration * 1000);
497	        this.contextItems = this.contextItems.filter(item => item.timestamp >= cutoff);
498	
499	        // Safety limit
500	        if (this.contextItems.length > this.maxContextItems) {
501	            this.contextItems = this.contextItems.slice(-this.maxContextItems);
502	        }
503	    }
504	
505	    /**
506	     * Compact transcript buffer by summarizing oldest entries into an epoch summary.
507	     * Called instead of raw slice() to preserve early meeting context.
508	     */
509	    private async compactTranscriptIfNeeded(): Promise<void> {
510	        if (this.fullTranscript.length <= 1800 || this.isCompacting) return;
511	
512	        this.isCompacting = true;
513	        try {
514	            // Take the oldest 500 entries to summarize
515	            const summarizeCount = 500;
516	            const oldEntries = this.fullTranscript.slice(0, summarizeCount);
517	            const summaryInput = oldEntries.map(seg => {
518	                const role = this.mapSpeakerToRole(seg.speaker);
519	                const label = role === 'interviewer' ? 'INTERVIEWER' :
520	                    role === 'user' ? 'ME' : 'ASSISTANT';
521	                return `[${label}]: ${seg.text}`;
522	            }).join('\n');
523	
524	            // Fire-and-forget LLM summarization (non-blocking)
525	            if (this.recapLLM) {
526	                try {
527	                    const epochSummary = await this.recapLLM.generate(
528	                        `Summarize this conversation segment into 3-5 concise bullet points preserving key topics, decisions, and questions:\n\n${summaryInput}`
529	                    );
530	                    if (epochSummary && epochSummary.trim().length > 0) {
531	                        this.transcriptEpochSummaries.push(epochSummary.trim());
532	                        console.log(`[SessionTracker] Epoch summary created (${this.transcriptEpochSummaries.length} total)`);
533	                    } else {
534	                        // Empty LLM response — store a basic marker so context is not lost
535	                        const marker = `[Earlier discussion: ${oldEntries.length} segments — ${oldEntries.slice(0, 3).map(s => s.text.substring(0, 40)).join('; ')}...]`;
536	                        this.transcriptEpochSummaries.push(marker);
537	                    }
538	                } catch (e) {
539	                    // If summarization fails, store a simple marker
540	                    const fallback = `[Earlier discussion: ${oldEntries.length} segments, topics: ${oldEntries.slice(0, 3).map(s => s.text.substring(0, 40)).join('; ')}...]`;
541	                    this.transcriptEpochSummaries.push(fallback);
542	                    console.warn('[SessionTracker] Epoch summarization failed, using fallback marker');
543	                }
544	            } else {
545	                // BUG-03 fix: recapLLM not yet available — always push a plain marker so early
546	                // context is not silently discarded with no record in transcriptEpochSummaries.
547	                const marker = `[Earlier discussion (no LLM): ${oldEntries.length} segments — ${oldEntries.slice(0, 3).map(s => s.text.substring(0, 40)).join('; ')}...]`;
548	                this.transcriptEpochSummaries.push(marker);
549	                console.warn('[SessionTracker] recapLLM not available — storing plain epoch marker');
550	            }
551	
552	            // Cap epoch summaries to prevent LLM context window overflow
553	            if (this.transcriptEpochSummaries.length > SessionTracker.MAX_EPOCH_SUMMARIES) {
554	                this.transcriptEpochSummaries = this.transcriptEpochSummaries.slice(-SessionTracker.MAX_EPOCH_SUMMARIES);
555	            }
556	
557	            // Evict ONLY the exact 500 oldest entries that we just summarized
558	            this.fullTranscript = this.fullTranscript.slice(summarizeCount);
559	        } finally {
560	            this.isCompacting = false;
561	        }
562	    }
563	}
